{
  "technical_and_design_decisions": [
    "Baseline on Spring Framework 6.x / Spring Boot 3.x with Java 17, consistent with the stated Spring 6.0 Java 17+ requirement.",
    "Extend the existing s-c-d (xd-admin) orchestration layer to drive YARN deployments using a manifest file that declares module placement and required assets.",
    "Stage YARN application artifacts (jars, configs) into HDFS using the Apache Hadoop HDFS client API before application submission.",
    "Integrate with the YARN ResourceManager REST API to submit, group and monitor module deployments as YARN applications, honoring appType=CLOUDDATA and appName=spring-cloud-data-yarn-app.",
    "Adopt a deployment-properties convention (e.g., module.<label>.yarn.app.name, plus queue, priority, memory, cpu keys) to map modules to named YARN app instances with distinct queues and priorities.",
    "Implement the deployer asynchronously using a task executor and an internal deployment task queue so the shell returns immediately with a task handle for status polling.",
    "Refactor the s-c-s ModuleLauncher contract onto Spring Boot's JarLauncher API to remove duplicated launching/classloading functionality.",
    "Resolve module dependency JARs at launch time (repository-based resolution) and append them plus user-provided external libraries to the Boot loader classpath in a uniform way."
  ],
  "assumptions": [
    "A single developer (the estimator) performs all work; estimates are effort in work-hours, not elapsed calendar time, and exclude waiting/blocking periods.",
    "An existing s-c-d/s-c-s codebase, a build system, and access to a test Hadoop/YARN cluster with HDFS and ResourceManager REST endpoints are available.",
    "No changes to the Spring Framework itself are required; all work occurs in the s-c-d and s-c-s modules described by the user stories.",
    "Each implementation activity includes its own developer-level unit tests; dedicated integration/system testing and documentation are estimated as separate activities.",
    "Hadoop/YARN versions are compatible with the HDFS and ResourceManager REST APIs used; no cluster administration work is included.",
    "Requirements are stable as written; rework due to changing requirements is excluded, while normal defect fixing is covered by the review/fix activity.",
    "The JAR-resolution experiment (U5) is a time-boxed technical spike whose outcome feeds U7 and U8."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Technical design and architecture",
      "activity_description": "Analyze U1-U8; design the deployment manifest format, xd-admin orchestration flow, HDFS staging approach, ResourceManager REST integration, async execution model, JarLauncher-based module launching, and the external library resolution strategy.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A2",
      "activity_name": "HDFS deployment support (U1)",
      "activity_description": "Implement automatic staging/deployment of the YARN application into HDFS, manifest parsing, and xd-admin orchestration hooks so deployments are placed with the correct assets.",
      "most_likely_effort": 60
    },
    {
      "activity_id": "A3",
      "activity_name": "ResourceManager REST negotiation (U2)",
      "activity_description": "Implement the YARN ResourceManager REST API client to submit and monitor module groups as YARN applications, including appType=CLOUDDATA and appName=spring-cloud-data-yarn-app handling and instrumentation for automatic app instance startup.",
      "most_likely_effort": 64
    },
    {
      "activity_id": "A4",
      "activity_name": "Multiple app instances (U3)",
      "activity_description": "Implement parsing of deployment properties (e.g., module.*.yarn.app.name), grouping of modules into distinct YARN app instances, and per-instance configuration of queue, priority, memory and cpu reservations.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A5",
      "activity_name": "Asynchronous deployer (U4)",
      "activity_description": "Make the deployer asynchronous with a deployment task queue in YARN-facing operations so the shell returns quickly with a handle; add task status tracking and basic lifecycle management.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A6",
      "activity_name": "Boot loader JAR resolution spike (U5)",
      "activity_description": "Time-boxed experiment to resolve module-dependent JARs and add them to the Boot loader, evaluating approaches for handling external libraries required by out-of-the-box modules.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A7",
      "activity_name": "Refactor ModuleLauncher onto JarLauncher (U6)",
      "activity_description": "Refactor the s-c-s ModuleLauncher contract to build on Spring Boot's JarLauncher API, remove duplicated launching/classloading functionality, and update affected tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A8",
      "activity_name": "Docs and tests for JAR resolution (U7)",
      "activity_description": "Write reference documentation and test cases covering resolution and addition of JARs to the Boot loader, including a guide for porting modules with external dependencies.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A9",
      "activity_name": "External libraries support (U8)",
      "activity_description": "Implement the uniform mechanism to supply external libraries to modules and integrate them into the launcher classpath so modules can consume such dependencies consistently.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration and system testing",
      "activity_description": "End-to-end verification on a test YARN/HDFS cluster: manifest-driven deployment, ResourceManager submission, multiple app instances with differing queues/priorities, async deploy behavior, and external library loading.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A11",
      "activity_name": "Review, defect fixing, build/CI and packaging",
      "activity_description": "Perform code reviews, configure/update CI build for the new modules, fix defects found during testing, and package the software increment for release.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 404
  }
}

